const { chromium } = await import('file:///D:/Repos/angular-jig/node_modules/playwright/index.mjs');

const types = { '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html', '.svg': 'image/svg+xml', '.json': 'application/json', '.ico': 'image/x-icon' };
const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x').pathname;
  let file = path.join(root, url);
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(root, 'index.html');
  res.writeHead(200, { 'content-type': types[path.extname(file)] ?? 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
});
await new Promise((r) => server.listen(4311, r));

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
const check = (label, ok) => console.log(`${ok ? 'PASS' : 'FAIL'} ${label}`);

await page.goto('http://localhost:4311/detail/HRO-0007');
await page.getByRole('button', { name: 'Edit', exact: true }).click();
await page.locator('#hero-name').fill('Silverwing Prime');
await page.getByRole('button', { name: 'Save changes' }).click();
await page.waitForTimeout(300);
check('detail save shows notice', (await page.getByRole('status').textContent()).includes('Silverwing Prime saved'));

await page.getByRole('link', { name: 'Dashboard' }).first().click();
await page.waitForTimeout(300);
check('dashboard reflects edited name', (await page.locator('main').textContent()).includes('Silverwing Prime'));

await page.getByRole('link', { name: 'Roster' }).first().click();
await page.waitForTimeout(200);
check('roster reflects edited name', (await page.locator('main').textContent()).includes('Silverwing Prime'));

const search = page.getByRole('searchbox', { name: 'Search heroes' }).first();
await search.fill('Aurora');
await search.press('Enter');
await page.waitForTimeout(300);
check('topbar search sets ?q=', page.url().includes('q=Aurora'));
const rowsAfterSearch = await page.locator('app-roster-table tbody tr').count();
check(`search narrows roster to 1 row (got ${rowsAfterSearch})`, rowsAfterSearch === 1);

await page.getByRole('link', { name: 'Recruit' }).first().click();
await page.getByLabel('Hero name').fill('Test Recruit');
await page.getByLabel('Alias').fill('Tester');
await page.getByRole('button', { name: 'Add to roster' }).click();
await page.waitForTimeout(400);
check('recruit opens new detail record', (await page.locator('h1').textContent()).includes('Test Recruit'));

await page.getByRole('link', { name: 'Roster' }).first().click();
await page.waitForTimeout(200);
check('new recruit appears on roster', (await page.locator('main').textContent()).includes('Test Recruit'));

await page.getByRole('link', { name: 'Missions' }).first().click();
await page.waitForTimeout(200);
check('missions screen renders', (await page.locator('h1').textContent()) === 'Missions');

await page.getByRole('link', { name: 'Threats' }).first().click();
await page.waitForTimeout(200);
check('threats screen renders', (await page.locator('h1').textContent()) === 'Threats');

await page.getByRole('link', { name: 'Settings' }).first().click();
await page.getByRole('switch').click();
await page.waitForTimeout(200);
check('settings toggles dark theme', await page.evaluate(() => document.documentElement.classList.contains('dark')));

check(`no runtime errors (${errors.length})`, errors.length === 0);
errors.forEach((e) => console.log('  err:', e.slice(0, 300)));
await browser.close();
server.close();

